-- Generated by tools/generate.py from bricksurance-data-core model v0.16.0.
-- Do not edit: change the spec in model/ and regenerate.

CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.vw_golden_thread
COMMENT 'The full digital twin walked end to end for the hero policy: quote -> bind -> MTA -> earn -> loss -> as-at version -> cede -> reserve -> capital -> fair value. One row per hop, and every hop is a real key join across domains (not a narrative) - the proof that underwriting, claims, finance, reinsurance, reserving and conduct are one governed estate. Hero: POL-2026-000001 / CLM-2026-000001 / TR-QS-PROP-2026. Grain: One row per hop of the golden thread.'
AS
WITH hero AS (
  SELECT policy_id FROM lr_serverless_aws_us_catalog.bricksurance_policy.policy WHERE policy_number = 'POL-2026-000001'
)
SELECT 1 AS hop_order, 'Quote' AS hop, 'quote for the hero risk' AS detail,
       CAST((SELECT quoted_gross_premium FROM lr_serverless_aws_us_catalog.bricksurance_policy.quote
             WHERE policy_id = (SELECT policy_id FROM hero) LIMIT 1) AS DECIMAL(18,2)) AS amount
UNION ALL
SELECT 2, 'Bind', 'policy bound (lifecycle event)',
       CAST((SELECT COUNT(*) FROM lr_serverless_aws_us_catalog.bricksurance_policy_lifecycle.policy_event
             WHERE policy_id = (SELECT policy_id FROM hero)
               AND policy_event_type_code = 'BOUND') AS DECIMAL(18,2))
UNION ALL
SELECT 3, 'MTA', 'mid-term sum-insured change before the loss',
       CAST((SELECT sum_insured_delta FROM lr_serverless_aws_us_catalog.bricksurance_policy_lifecycle.policy_event
             WHERE policy_id = (SELECT policy_id FROM hero)
               AND policy_event_type_code = 'MTA_APPLIED' LIMIT 1) AS DECIMAL(18,2))
UNION ALL
SELECT 4, 'Earn', 'earned premium to date',
       CAST((SELECT earned_premium FROM lr_serverless_aws_us_catalog.bricksurance_semantics.premium_earning
             WHERE policy_id = (SELECT policy_id FROM hero) LIMIT 1) AS DECIMAL(18,2))
UNION ALL
SELECT 5, 'Loss / reserve', 'hero claim outstanding case reserve (derived)',
       CAST((SELECT SUM(ct.amount) FROM lr_serverless_aws_us_catalog.bricksurance_claim.claim_transaction ct
             JOIN lr_serverless_aws_us_catalog.bricksurance_claim.claim c ON c.claim_id = ct.claim_id
             WHERE c.claim_number = 'CLM-2026-000001'
               AND ct.claim_transaction_type_code = 'CASE_RESERVE_MOVEMENT') AS DECIMAL(18,2))
UNION ALL
SELECT 6, 'As-at version', 'policy version in force at the loss',
       CAST((SELECT pv.version_no FROM lr_serverless_aws_us_catalog.bricksurance_claim.claim c
             JOIN lr_serverless_aws_us_catalog.bricksurance_policy_lifecycle.policy_version pv ON pv.policy_version_id = c.policy_version_id
             WHERE c.claim_number = 'CLM-2026-000001') AS DECIMAL(18,2))
UNION ALL
SELECT 7, 'Cede', 'quota share ceded to the treaty',
       CAST((SELECT ces.ceded_share FROM lr_serverless_aws_us_catalog.bricksurance_reinsurance.cession ces
             WHERE ces.policy_id = (SELECT policy_id FROM hero) LIMIT 1) AS DECIMAL(18,2))
UNION ALL
SELECT 8, 'Reserve (actuarial)', 'commercial property ultimate (chain ladder)',
       CAST((SELECT SUM(ultimate_loss) FROM lr_serverless_aws_us_catalog.bricksurance_reserving.reserve_estimate
             WHERE line_of_business_code = 'COMMERCIAL_PROPERTY' AND reserving_method_code = 'CHAIN_LADDER') AS DECIMAL(18,2))
UNION ALL
SELECT 9, 'Capital', 'commercial property published case reserve (GBP)',
       CAST((SELECT amount FROM lr_serverless_aws_us_catalog.bricksurance_finance.valuation_result
             WHERE valuation_measure_code = 'CASE_RESERVE_TOTAL'
               AND line_of_business_code = 'COMMERCIAL_PROPERTY' AND currency_code = 'GBP' LIMIT 1) AS DECIMAL(18,2))
UNION ALL
SELECT 10, 'Fair value', 'commercial property Consumer Duty verdict (0=fair,1=monitor)',
       CAST((SELECT CASE WHEN fair_value_outcome_code = 'FAIR' THEN 0 ELSE 1 END
             FROM lr_serverless_aws_us_catalog.bricksurance_semantics.vw_fair_value_latest
             WHERE line_of_business_code = 'COMMERCIAL_PROPERTY') AS DECIMAL(18,2));
